```
using System;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;

class MyHttpServer
{
    static HttpListener listener = new HttpListener();

    static void Main(string[] args)
    {
        Console.WriteLine("Starting HTTP server on port 8080...");

        listener.Prefixes.Add("http://localhost:8080/");
        listener.Start();

        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            if (request.Url.AbsolutePath == "/")
            {
                HandleHelloRequest(context);
            }
            else
            {
                HandleNotFound(context);
            }
        }
    }

    static void HandleHelloRequest(HttpListenerContext context)
    {
        string response = "<html><body>Hello</body></html>";
        context.Response.ContentType = "text/html";
        context.Response.ContentLength64 = response.Length;
        using (StreamWriter writer = new StreamWriter(context.Response.OutputStream))
        {
            writer.Write(response);
        }
    }

    static void HandleNotFound(HttpListenerContext context)
    {
        string response = "<html><body>Not Found</body></html>";
        context.Response.StatusCode = 404;
        context.Response.ContentType = "text/html";
        context.Response.ContentLength64 = response.Length;
        using (StreamWriter writer = new StreamWriter(context.Response.OutputStream))
        {
            writer.Write(response);
        }
    }
}
```
Ce programme utilise l'objet `HttpListener` pour écouter les requêtes HTTP sur le port 8080. Lorsqu'une requête est reçue, le programme vérifie si la route est `/` (ce qui signifie la racine du site) ou une autre route.

Si la route est `/`, le programme appelle la méthode `HandleHelloRequest` pour répondre à la requête en envoyant un réponse HTML avec le texte "Hello".

Si la route est autre chose que `/`, le programme appelle la méthode `HandleNotFound` pour répondre à la requête en envoyant un réponse HTML avec le texte "Not Found" et un code d'état 404.

Notez que ce programme ne gère pas les erreurs et les exceptions, ce qui signifie que si quelque chose se produit incorrectement, le programme peut planter. Dans un environnement de production, il est important de gérer les erreurs et les exceptions correctement.

